"""Library for Switch related operations.

    = Configuration Needed =
    === testline_config ===
    | "wireshark_host": {       Section defining machine details of where IPSEC ESP key decryption must happen
    |		"ip": "",               IP address
    |		"user": "",             username
    |		"password": "",         password
    | }

    | "secure_gw": {
    |	"type": "",                 Type of Ipsec tool. Values: strongswan
    |	"ip": "",                   IP address for ipsec machine
    |	"user": "",                 username for ipsec machine
    |	"password": "",             password for ipsec machine
    |	"ipsec_conf_path": "",      IPsec config path
    |	"connections" : ["BTS-{btsid}-5VLAN-GSM"]       Connection list on the ipsec machine
    | },

    | *"bts"*: {                Not supported yet
    |
    | },

   === tunnel_analysis ===
   | "tunnel_analysis": {
   |    "tunnel_profile1": {
   |    "ike_tunnel1": [{
   |           "end_points": "ike_ip1=>ike_ip2",
   |           "esp_tunnels": [
   |             {
   |                "end_points": "esp_ip1=>esp_ip2",
   |                "should_exist": "true"
   |             },
   |             {
   |                "end_points": "esp_ip3=>esp_ip4",
   |                "should_exist": "true"
   |             }],
   |           "should_exist": "true"
   |         }]
   |   }}

"""

from taf.ul.trs_e2e_fw.lib.ipsec.ipsec import Ipsec
from taf.ul.trs_e2e_fw.lib.ipsec.generate_esp_sa import generate_esp_sa
from taf.ul.trs_e2e_fw.lib.ipsec.isakmp import Isakmp


def ipsec_config(source="both", alias="default"):
    """This keyword is used to configure ipsec on BTS and secure gateway. \n
    Not supported yet. Ipsec config is right now handled by commissioning by user.

       | *Arguments* | *Comments* | *Default Value* |
       | source | This variable can be used to define where to configure ipsec. Values: secure_gw, bts, both | both |
       | alias |  | 'default' |

        *Usage :*

            _Ipsec Config	|	<source>    |   <alias>_

        *Examples:*

        *Configure IPSEC on both bts and secure_gw*
        | Ipsec Config |
        *Configure IPSEC on secure_gw*
        | IPsec Config | source=secure_gw |

    *Configurations Needed :*

    `testline_config` sections:

    "secure_gw" \n
    "bts"

    """

    return Ipsec().ipsec_config(source=source, alias=alias)


def ipsec_enable(source="bts", alias="default", device="default"):
    """This keyword is used to enable ipsec.

       | *Arguments* | *Comments* | *Default Value* |
       | source | This variable can be used to define where to enable ipsec. Values: secure_gw, bts, both | bts |
       | device | Specifies the device name in testline_config under section secure_gw |
       | alias |  | 'default' |

        *Usage :*

            _Ipsec Enable	|	<source>    |   <alias>_

        *Examples:*

        *Enable IPSEC on bts *
        | Enable Config | source=bts |
        *Enable IPSEC on secure_gw*
        | Enable Config | source=secure_gw |

    *Configurations Needed :*

    `testline_config` sections:

    "secure_gw" \n
    "bts"

    """

    return Ipsec().ipsec_enable(source=source, alias=alias, device=device)


def ipsec_disable(source="bts", alias="default", device="default"):
    """This keyword is used to enable ipsec.

       | *Arguments* | *Comments* | *Default Value* |
       | source | This variable can be used to define where to disable ipsec. Values: secure_gw, bts, both | bts |
       | alias |  | 'default' |

        *Usage :*

            _Ipsec Disable	<source>      <alias>_

    *Configurations Needed :*

    `testline_config` sections:

    "secure_gw" \n
    "bts"

    """
    return Ipsec().ipsec_disable(source=source, alias=alias, device=device)


def ipsec_get_conf_parameter(parameter, connections="all", source="secure_gw"):
    """This keyword can be used to retrieve parameter from IPSEC configuration.

        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | parameter | Mandatory | Parameter name that need to be retrieved |  |
        | connections | 'all' | connection name in the config file, from which the parameter needs to retrieved |  |
        | source | 'secure_gw' | This variable can be used to define ipsec source endpoint. Values: secure_gw, bts,
        |  |  | both | |

         *Usage :*

             _Ipsec Get Conf Parameter	|	<parameter>    |   <connections>  | <source>_

         *Examples:*

         *Retrieve keyexchange value from bts Ipsec config*
         | Ipsec Get Conf Parameter | keyexchange | source=bts |
         *Retrieve keyexchange value from bts Ipsec secure_gw*
         | Ipsec Get Conf Parameter | keyexchange | source=secure_gw |

    *Return:*
    It will return the value of teh given parameter.

    *Configurations Needed :*

    `testline_config` sections:

    "secure_gw" \n
    "bts"

     """
    return Ipsec().ipsec_get_conf_parameter(parameter, connections=connections, source=source)


def ipsec_modify_policy_parameters(connections="all", source="secure_gw", **parameters):
    """This keyword can be used to modify IPSEC policy parameters.

        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | connections | all | Connection name in the config file, where the parameter needs to be modified |  |
        | source | secure_gw | This variable can be used to define ipsec source endpoint. Values: secure_gw,bts,both | |
        | parameters | Optional | List of parameters |

         *Usage :*

             _Ipsec Get Conf Parameter	|	<parameter>    |   <connections>  | <source>_

         *Examples:*
         *Modify keyexchange value from bts Ipsec config*
         | Ipsec Modify Policy Parameters | keyexchange=ikev2 | source=bts |

    *Configurations Needed :*

    `testline_config` sections:

    "secure_gw" \n
    "bts"

    """

    Ipsec().ipsec_modify_policy_parameters(connections=connections, source=source, **parameters)


def generate_esp_sa_key_file(wireshark_host, esp_sa_file='/home/ute/.wireshark/esp_sa'):
    """
    Generate key file for decrypting ESP encryped packets on wireshark. This keyword will get the
    keys from the bts and put it in the esp_sa_file file.
    After the keys are added, executing tshark commands, will show teh decrypted packets.

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | wireshark_host | Mandatory | Host name in which the decryption must happen. Defined in testline_config.json, |
    |  |  |  | `testline_config` section "wireshark_host" |
    | esp_sa_file | '/home/ute/.wireshark/esp_sa' | esp sa file location |  |

    *Configurations Needed :*

    `testline_config` sections:

    "wireshark_host"

    """
    generate_esp_sa().generate_esp_sa_key_file(wireshark_host, esp_sa_file=esp_sa_file)


def ipsec_verify_status(**kwargs):
    """This keyword can be used verify the IPSEC status.

        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | scf | None | all |    |
        | source | 'bts' | source can be rf_module/bts/secure_gw |    |
        | device | 'bts' | all |    |
        | profile | None | Mandatory if IKE, ESP tunnels need to be verified | `tunnel_analysis` |
        | tunnel_analysis_file | 'tunnel_analysis.json' | Optional, name of the file where  |  |
        |                |                   | tunnel information is stored | `tunnel_analysis` |
        | rfmod_inst_id | Mandatory | Only mandatory if source is rf_module |
        | iprange | None | Only valid if source is rf_module |

         *Usage :*

             Ipsec Verify Status	|	<parameter>    |   <connections>  | <source> |

         *Examples:*

         *Retrieve an  IPSEC param from bts *
         | Ipsec Verify Status | source=bts |
         *Retrieve an  IPSEC param from bts*
         | Ipsec Verify Status | source=secure_gw |
         *Retrieve an  IPSEC param from bts*
         | Ipsec Verify Status | source=rf_module |

    *Configurations Needed :*

    `testline_config` sections:

    "secure_gw" \n
    "bts" \n
    "rf_module"

    """

    Ipsec().ipsec_verify_status(**kwargs)


def perform_isakmp_decryption(ipsec_gateway_section="default", bts_section="bts", **kwargs):
    """This keyword can be used for isakmp decryption.

    | *Arguments* | *Default Value* | *Comments* |
    | ipsec_gateway_section | 'default' | section in testline config json file which contains details about security |
    |  |  | gateway | |
    | bts_section | 'bts' | section in testline config json file which contains details about bts | |

     *Usage :*

         _Perform Isakmp Decryption	|	<ipsec_gateway_section>_

     *Examples:*

     | Perfrom Isakmp Decryption | ipsec_gateway_section=secure_gw | bts_section="bts" |
     | Perfrom Isakmp Decryption | ipsec_gateway_section=secure_gw |

    """
    Isakmp().perform_isakmp_decryption(ipsec_gateway_section=ipsec_gateway_section,
                                       bts_section=bts_section, **kwargs)
